// Generated by the website's scripts/build-peppol-ubl-check.ts from its own copy of these tests; edit there.
import { readFileSync } from "node:fs";
import { resolve } from "node:path";
import { describe, expect, it } from "vitest";
import { validateInvoiceXml, type ValidationProfile } from "../src/engine/validate";


/** The website's sample invoices, as written to test/fixtures/. */
const SAMPLES: Record<string, string> = {
  "peppol-valid": "valid/peppol-bis3-valid-be.xml",
  "credit-note-valid": "valid/peppol-credit-note.xml",
  "reverse-charge-valid": "valid/reverse-charge-de-nl.xml",
  "vat-calculation-error": "invalid/invalid-vat-calculation.xml",
  "missing-mandatory": "invalid/missing-mandatory-fields.xml",
  "be-endpoint-errors": "invalid/be-endpoint-errors.xml",
  "malformed-xml": "invalid/malformed.xml",
  "de-xrechnung-ubl-valid": "xrechnung/xrechnung-ubl-valid.xml",
  "de-xrechnung-cii-valid": "xrechnung/xrechnung-cii-valid.xml",
  "de-xrechnung-ubl-errors": "xrechnung/xrechnung-ubl-errors.xml",
  "de-xrechnung-cii-errors": "xrechnung/xrechnung-cii-errors.xml",
  "nl-si-ubl-valid": "nlcius/si-ubl-valid.xml",
  "nl-si-ubl-errors": "nlcius/si-ubl-errors.xml",
  "factur-x-en16931": "factur-x/factur-x-en16931.xml"
};
const getSample = (id: string) =>
  SAMPLES[id] ? { content: readFileSync(resolve(__dirname, "fixtures", SAMPLES[id]!), "utf8") } : undefined;

/**
 * Official verdicts beyond the calculation margins, held to the rule sets the checker follows:
 * Peppol BIS Billing 3.0.22 (PEPPOL-EN16931-UBL.sch and -CII.sch) and the CEN EN 16931 rules
 * 1.3.17. The Peppol unit tests may not be redistributed, so each case here restates one of them
 * (the file it comes from is named) in our own minimal invoice; the CEN cases are vendored in
 * src/test/fixtures/en16931-cen and run by official-margins.test.ts.
 */

const UBL_NS =
  'xmlns:cac="urn:oasis:names:specification:ubl:schema:xsd:CommonAggregateComponents-2" xmlns:cbc="urn:oasis:names:specification:ubl:schema:xsd:CommonBasicComponents-2"';
const ubl = (body: string, root: "Invoice" | "CreditNote" = "Invoice") =>
  `<?xml version="1.0" encoding="UTF-8"?>\n<${root} xmlns="urn:oasis:names:specification:ubl:schema:xsd:${root}-2" ${UBL_NS}>${body}</${root}>`;
const cii = (body: string) =>
  `<?xml version="1.0" encoding="UTF-8"?>\n<rsm:CrossIndustryInvoice xmlns:rsm="urn:un:unece:uncefact:data:standard:CrossIndustryInvoice:100" xmlns:ram="urn:un:unece:uncefact:data:standard:ReusableAggregateBusinessInformationEntity:100" xmlns:udt="urn:un:unece:uncefact:data:standard:UnqualifiedDataType:100">${body}</rsm:CrossIndustryInvoice>`;
const PEPPOL_CID = "urn:cen.eu:en16931:2017#compliant#urn:fdc:peppol.eu:2017:poacc:billing:3.0";
const PEPPOL_PROFILE = "urn:fdc:peppol.eu:2017:poacc:billing:01:1.0";
const ciiContext = (cid = PEPPOL_CID, profile: string | null = PEPPOL_PROFILE) =>
  `<rsm:ExchangedDocumentContext>${profile === null ? "" : `<ram:BusinessProcessSpecifiedDocumentContextParameter><ram:ID>${profile}</ram:ID></ram:BusinessProcessSpecifiedDocumentContextParameter>`}<ram:GuidelineSpecifiedDocumentContextParameter><ram:ID>${cid}</ram:ID></ram:GuidelineSpecifiedDocumentContextParameter></rsm:ExchangedDocumentContext>`;
const ciiTx = (parts: { agreement?: string; delivery?: string; settlement?: string; lines?: string }) =>
  `<rsm:SupplyChainTradeTransaction>${parts.lines ?? ""}<ram:ApplicableHeaderTradeAgreement>${parts.agreement ?? ""}</ram:ApplicableHeaderTradeAgreement><ram:ApplicableHeaderTradeDelivery>${parts.delivery ?? ""}</ram:ApplicableHeaderTradeDelivery><ram:ApplicableHeaderTradeSettlement>${parts.settlement ?? ""}</ram:ApplicableHeaderTradeSettlement></rsm:SupplyChainTradeTransaction>`;

type Verdict = "error" | "warning" | "success";
/** How the checker answers for one rule: its worst finding (info doesn't count). */
function verdict(xml: string, rule: string, profile: ValidationProfile = "peppol"): Verdict {
  const own = validateInvoiceXml(xml, profile).findings.filter((f) => f.ruleId === rule && f.severity !== "info");
  return own.some((f) => f.severity === "error") ? "error" : own.length ? "warning" : "success";
}

describe("Peppol BIS 3.0 on UBL: element presence, as the official rules test it", () => {
  it("R001 accepts an empty ProfileID element (PEPPOL-EN16931-R001.xml); R008 reports the emptiness", () => {
    const xml = ubl("<cbc:ProfileID/>");
    expect(verdict(xml, "PEPPOL-EN16931-R001")).toBe("success");
    expect(verdict(xml, "PEPPOL-EN16931-R008")).toBe("error");
  });
  it("a missing ProfileID breaks R001 and R007 (the official $profile is then 'Unknown')", () => {
    const xml = ubl(`<cbc:CustomizationID>${PEPPOL_CID}</cbc:CustomizationID>`);
    expect(verdict(xml, "PEPPOL-EN16931-R001")).toBe("error");
    expect(verdict(xml, "PEPPOL-EN16931-R007")).toBe("error");
  });
  it("R003 accepts an empty buyer reference or order reference ID (PEPPOL-EN16931-R003.xml)", () => {
    expect(verdict(ubl("<cbc:BuyerReference/>"), "PEPPOL-EN16931-R003")).toBe("success");
    expect(verdict(ubl("<cac:OrderReference><cbc:ID/></cac:OrderReference>"), "PEPPOL-EN16931-R003")).toBe("success");
    expect(verdict(ubl("<cac:OrderReference><cbc:SalesOrderID>1</cbc:SalesOrderID></cac:OrderReference>"), "PEPPOL-EN16931-R003")).toBe("error");
  });
  it("R061 accepts an empty mandate ID and needs the element for codes 49 and 59 (PEPPOL-EN16931-R061.xml)", () => {
    const pm = (code: string, mandate: string) => ubl(`<cac:PaymentMeans><cbc:PaymentMeansCode>${code}</cbc:PaymentMeansCode>${mandate}</cac:PaymentMeans>`);
    expect(verdict(pm("49", "<cac:PaymentMandate><cbc:ID/></cac:PaymentMandate>"), "PEPPOL-EN16931-R061")).toBe("success");
    expect(verdict(pm("59", "<cac:PaymentMandate><cbc:ID>M-1</cbc:ID></cac:PaymentMandate>"), "PEPPOL-EN16931-R061")).toBe("success");
    expect(verdict(pm("59", ""), "PEPPOL-EN16931-R061")).toBe("error");
    expect(verdict(pm("30", ""), "PEPPOL-EN16931-R061")).toBe("success");
  });
});

describe("Peppol BIS 3.0 on UBL: values and code lists", () => {
  it("R043 checks line-level allowances and charges too (PEPPOL-EN16931-R043.xml)", () => {
    const line = (tag: string, ind: string) => `<cac:${tag}><cac:AllowanceCharge><cbc:ChargeIndicator>${ind}</cbc:ChargeIndicator></cac:AllowanceCharge></cac:${tag}>`;
    expect(verdict(ubl(line("InvoiceLine", "0")), "PEPPOL-EN16931-R043")).toBe("error");
    expect(verdict(ubl(line("CreditNoteLine", "0"), "CreditNote"), "PEPPOL-EN16931-R043")).toBe("error");
    expect(verdict(ubl(line("InvoiceLine", "false")), "PEPPOL-EN16931-R043")).toBe("success");
    expect(verdict(ubl("<cac:AllowanceCharge><cbc:ChargeIndicator>TRUE</cbc:ChargeIndicator></cac:AllowanceCharge>"), "PEPPOL-EN16931-R043")).toBe("error");
  });
  it("R044 accepts only the literal 'false' on price level (PEPPOL-EN16931-R044.xml)", () => {
    const price = (ind: string) => ubl(`<cac:InvoiceLine><cac:Price><cac:AllowanceCharge><cbc:ChargeIndicator>${ind}</cbc:ChargeIndicator></cac:AllowanceCharge></cac:Price></cac:InvoiceLine>`);
    expect(verdict(price("0"), "PEPPOL-EN16931-R044")).toBe("error");
    expect(verdict(price("true"), "PEPPOL-EN16931-R044")).toBe("error");
    expect(verdict(price("false"), "PEPPOL-EN16931-R044")).toBe("success");
  });
  it("R051 covers every listed amount, including the line price (PEPPOL-EN16931-R051.xml)", () => {
    const doc = (price: string) =>
      ubl(`<cbc:DocumentCurrencyCode>EUR</cbc:DocumentCurrencyCode><cac:TaxTotal><cbc:TaxAmount currencyID="EUR">10</cbc:TaxAmount><cac:TaxSubtotal><cbc:TaxAmount currencyID="EUR">10</cbc:TaxAmount></cac:TaxSubtotal></cac:TaxTotal><cac:InvoiceLine><cbc:LineExtensionAmount currencyID="EUR">100</cbc:LineExtensionAmount><cac:Price>${price}</cac:Price></cac:InvoiceLine>`);
    expect(verdict(doc('<cbc:PriceAmount currencyID="NOK">100</cbc:PriceAmount>'), "PEPPOL-EN16931-R051")).toBe("error");
    expect(verdict(doc('<cbc:PriceAmount currencyID="EUR">100</cbc:PriceAmount><cac:AllowanceCharge><cbc:ChargeIndicator>false</cbc:ChargeIndicator><cbc:Amount currencyID="SEK">1</cbc:Amount></cac:AllowanceCharge>'), "PEPPOL-EN16931-R051")).toBe("error");
    expect(verdict(doc('<cbc:PriceAmount currencyID="EUR">100</cbc:PriceAmount>'), "PEPPOL-EN16931-R051")).toBe("success");
  });
  it("R051 leaves the VAT total in the accounting currency (a TaxTotal without subtotals) alone", () => {
    const xml = ubl(`<cbc:DocumentCurrencyCode>EUR</cbc:DocumentCurrencyCode><cbc:TaxCurrencyCode>SEK</cbc:TaxCurrencyCode><cac:TaxTotal><cbc:TaxAmount currencyID="EUR">10</cbc:TaxAmount><cac:TaxSubtotal><cbc:TaxAmount currencyID="EUR">10</cbc:TaxAmount></cac:TaxSubtotal></cac:TaxTotal><cac:TaxTotal><cbc:TaxAmount currencyID="SEK">110</cbc:TaxAmount></cac:TaxTotal>`);
    expect(verdict(xml, "PEPPOL-EN16931-R051")).toBe("success");
  });
  it("R053 needs exactly one TaxTotal with subtotals, so none fails as well (PEPPOL-EN16931-R053.xml)", () => {
    const tt = '<cac:TaxTotal><cbc:TaxAmount currencyID="EUR">10</cbc:TaxAmount><cac:TaxSubtotal/></cac:TaxTotal>';
    expect(verdict(ubl(""), "PEPPOL-EN16931-R053")).toBe("error");
    expect(verdict(ubl(tt), "PEPPOL-EN16931-R053")).toBe("success");
    expect(verdict(ubl(tt + tt), "PEPPOL-EN16931-R053")).toBe("error");
  });
  it("P0100 and P0101 only apply under an approved business process (PEPPOL-EN16931-P0100.xml, -P0101.xml)", () => {
    const inv = (profile: string) => ubl(`<cbc:ProfileID>${profile}</cbc:ProfileID><cbc:InvoiceTypeCode>999</cbc:InvoiceTypeCode>`);
    const cn = (profile: string) => ubl(`<cbc:ProfileID>${profile}</cbc:ProfileID><cbc:CreditNoteTypeCode>380</cbc:CreditNoteTypeCode>`, "CreditNote");
    expect(verdict(inv("urn:www.cenbii.eu:profile:bii04:ver1.0"), "PEPPOL-EN16931-P0100")).toBe("success");
    expect(verdict(inv(PEPPOL_PROFILE), "PEPPOL-EN16931-P0100")).toBe("error");
    expect(verdict(cn("urn:www.cenbii.eu:profile:bii04:ver1.0"), "PEPPOL-EN16931-P0101")).toBe("success");
    expect(verdict(cn("urn:peppol:bis:billing_with_response"), "PEPPOL-EN16931-P0101")).toBe("error");
  });
  it("CL008 checks every EndpointID with a schemeID, wherever it sits (PEPPOL-COMMON-EAS.xml)", () => {
    const xml = (scheme: string) => ubl(`<cac:AccountingSellerParty><cac:Party><cbc:EndpointID schemeID="${scheme}">1234567890</cbc:EndpointID></cac:Party></cac:AccountingSellerParty>`);
    expect(verdict(xml("0207"), "PEPPOL-EN16931-CL008")).toBe("error");
    expect(verdict(xml("0007"), "PEPPOL-EN16931-CL008")).toBe("success");
  });
  it("COMMON-R043 checks 0208 numbers of every party, not only seller and buyer", () => {
    const xml = (id: string) => ubl(`<cac:PayeeParty><cac:PartyIdentification><cbc:ID schemeID="0208">${id}</cbc:ID></cac:PartyIdentification></cac:PayeeParty>`);
    expect(verdict(xml("0403.170.701"), "PEPPOL-COMMON-R043")).toBe("error");
    expect(verdict(xml("0403170701"), "PEPPOL-COMMON-R043")).toBe("success");
  });
  it("COMMON-R040 (GLN) is a Peppol rule: EN 16931 alone doesn't check the GS1 check digit", () => {
    const xml = ubl('<cac:AccountingSupplierParty><cac:Party><cbc:EndpointID schemeID="0088">5790000435950</cbc:EndpointID></cac:Party></cac:AccountingSupplierParty>');
    expect(verdict(xml, "PEPPOL-COMMON-R040")).toBe("error");
    expect(verdict(xml, "PEPPOL-COMMON-R040", "en16931")).toBe("success");
  });
});

describe("Peppol BIS 3.0 on CII (OpenPeppol's PEPPOL-EN16931-CII.sch)", () => {
  it("a CII invoice that declares Peppol BIS 3.0 is checked as Peppol automatically", () => {
    const r = validateInvoiceXml(cii(ciiContext()), "auto");
    expect(r.format.id).toBe("peppol-bis-3-cii");
    expect(r.profileApplied).toBe("peppol");
  });
  it("other CII files keep their own rule set under 'auto' (Factur-X sample: no Peppol findings)", () => {
    const r = validateInvoiceXml(getSample("factur-x-en16931")!.content, "auto");
    expect(r.profileApplied).toBe("en16931");
    expect(r.findings.filter((f) => f.source === "Peppol")).toEqual([]);
  });
  it("the 'peppol' profile checks other CII files as Peppol, but leaves Factur-X and XRechnung CII to their own rules", () => {
    expect(validateInvoiceXml(cii(ciiContext("urn:example:own-cius")), "peppol").profileApplied).toBe("peppol");
    for (const id of ["factur-x-en16931", "de-xrechnung-cii-valid"]) {
      const r = validateInvoiceXml(getSample(id)!.content, "peppol");
      expect(r.profileApplied, id).not.toBe("peppol");
      expect(r.findings.filter((f) => f.source === "Peppol"), id).toEqual([]);
    }
  });
  it("R001, R004 and R007 read the CII document context (PEPPOL-EN16931-R001/R004/R007.xml)", () => {
    expect(verdict(cii(ciiContext(PEPPOL_CID, null)), "PEPPOL-EN16931-R001")).toBe("error");
    expect(verdict(cii(ciiContext()), "PEPPOL-EN16931-R001")).toBe("success");
    expect(verdict(cii(ciiContext("urn:cen.eu:en16931:2017#compliant#compliant#urn:www.difi.no:ehf:ver3.0")), "PEPPOL-EN16931-R004")).toBe("error");
    // CII approves only billing 01 and billing with response, not the French processes UBL accepts
    expect(verdict(cii(ciiContext(PEPPOL_CID, "urn:peppol:france:billing:regulated")), "PEPPOL-EN16931-R007")).toBe("error");
    expect(verdict(cii(ciiContext(PEPPOL_CID, "urn:peppol:bis:billing_with_response")), "PEPPOL-EN16931-R007")).toBe("success");
  });
  it("R002 allows one note without a subject code, and has no German exception in CII (PEPPOL-EN16931-R002.xml)", () => {
    const doc = (notes: string) => cii(`${ciiContext()}<rsm:ExchangedDocument>${notes}</rsm:ExchangedDocument>`);
    expect(verdict(doc("<ram:IncludedNote><ram:Content>A</ram:Content></ram:IncludedNote>"), "PEPPOL-EN16931-R002")).toBe("success");
    expect(verdict(doc("<ram:IncludedNote><ram:Content>A</ram:Content></ram:IncludedNote><ram:IncludedNote><ram:Content>B</ram:Content></ram:IncludedNote>"), "PEPPOL-EN16931-R002")).toBe("error");
    expect(verdict(doc("<ram:IncludedNote><ram:Content>A</ram:Content><ram:SubjectCode>AAI</ram:SubjectCode></ram:IncludedNote>"), "PEPPOL-EN16931-R002")).toBe("error");
  });
  it("R003, R010 and R020 ask for the CII elements (PEPPOL-EN16931-R003/R010/R020.xml)", () => {
    const withAgreement = (a: string) => cii(ciiContext() + ciiTx({ agreement: a }));
    expect(verdict(withAgreement(""), "PEPPOL-EN16931-R003")).toBe("error");
    expect(verdict(withAgreement("<ram:BuyerReference>REF</ram:BuyerReference>"), "PEPPOL-EN16931-R003")).toBe("success");
    expect(verdict(withAgreement("<ram:SellerTradeParty><ram:Name>S</ram:Name></ram:SellerTradeParty>"), "PEPPOL-EN16931-R020")).toBe("error");
    expect(verdict(withAgreement('<ram:BuyerTradeParty><ram:URIUniversalCommunication><ram:URIID schemeID="0208">0403170701</ram:URIID></ram:URIUniversalCommunication></ram:BuyerTradeParty>'), "PEPPOL-EN16931-R010")).toBe("success");
  });
  it("R043 covers document, line and price-level allowances in CII (PEPPOL-EN16931-R043.xml)", () => {
    const ac = (ind: string) => `<ram:SpecifiedTradeAllowanceCharge><ram:ChargeIndicator><udt:Indicator>${ind}</udt:Indicator></ram:ChargeIndicator></ram:SpecifiedTradeAllowanceCharge>`;
    expect(verdict(cii(ciiContext() + ciiTx({ settlement: ac("1") })), "PEPPOL-EN16931-R043")).toBe("error");
    expect(verdict(cii(ciiContext() + ciiTx({ settlement: ac("true") })), "PEPPOL-EN16931-R043")).toBe("success");
    const line = `<ram:IncludedSupplyChainTradeLineItem><ram:SpecifiedLineTradeAgreement><ram:GrossPriceProductTradePrice><ram:ChargeAmount>10</ram:ChargeAmount><ram:AppliedTradeAllowanceCharge><ram:ChargeIndicator><udt:Indicator>0</udt:Indicator></ram:ChargeIndicator></ram:AppliedTradeAllowanceCharge></ram:GrossPriceProductTradePrice></ram:SpecifiedLineTradeAgreement><ram:SpecifiedLineTradeSettlement>${ac("false")}</ram:SpecifiedLineTradeSettlement></ram:IncludedSupplyChainTradeLineItem>`;
    expect(verdict(cii(ciiContext() + ciiTx({ lines: line })), "PEPPOL-EN16931-R043")).toBe("error");
  });
  it("R053 counts the VAT totals in the invoice currency; R055 treats zero as positive in CII", () => {
    const sum = (totals: string, extra = "") =>
      cii(ciiContext() + ciiTx({ settlement: `${extra}<ram:InvoiceCurrencyCode>EUR</ram:InvoiceCurrencyCode><ram:SpecifiedTradeSettlementHeaderMonetarySummation>${totals}</ram:SpecifiedTradeSettlementHeaderMonetarySummation>` }));
    expect(verdict(sum('<ram:TaxTotalAmount currencyID="SEK">10</ram:TaxTotalAmount>'), "PEPPOL-EN16931-R053")).toBe("error");
    expect(verdict(sum('<ram:TaxTotalAmount currencyID="EUR">10</ram:TaxTotalAmount>'), "PEPPOL-EN16931-R053")).toBe("success");
    expect(verdict(sum('<ram:TaxTotalAmount currencyID="EUR">10</ram:TaxTotalAmount><ram:TaxTotalAmount currencyID="EUR">10</ram:TaxTotalAmount>'), "PEPPOL-EN16931-R053")).toBe("error");
    const signs = (doc: string, acct: string) =>
      `<ram:TaxTotalAmount currencyID="EUR">${doc}</ram:TaxTotalAmount><ram:TaxTotalAmount currencyID="SEK">${acct}</ram:TaxTotalAmount>`;
    const tax = "<ram:TaxCurrencyCode>SEK</ram:TaxCurrencyCode>";
    expect(verdict(sum(signs("0", "-1"), tax), "PEPPOL-EN16931-R055")).toBe("error");
    expect(verdict(sum(signs("-5", "-55"), tax), "PEPPOL-EN16931-R055")).toBe("success");
  });
  it("UBL's R055 accepts a zero VAT total next to a negative one (≤ 0 on both sides)", () => {
    const xml = ubl(`<cbc:DocumentCurrencyCode>EUR</cbc:DocumentCurrencyCode><cbc:TaxCurrencyCode>SEK</cbc:TaxCurrencyCode><cac:TaxTotal><cbc:TaxAmount currencyID="EUR">0</cbc:TaxAmount><cac:TaxSubtotal/></cac:TaxTotal><cac:TaxTotal><cbc:TaxAmount currencyID="SEK">-1</cbc:TaxAmount></cac:TaxTotal>`);
    expect(verdict(xml, "PEPPOL-EN16931-R055")).toBe("success");
  });
  it("R061 looks for the mandate in the payment terms (PEPPOL-EN16931-R061.xml)", () => {
    const pm = (terms: string) => cii(ciiContext() + ciiTx({ settlement: `<ram:SpecifiedTradeSettlementPaymentMeans><ram:TypeCode>59</ram:TypeCode></ram:SpecifiedTradeSettlementPaymentMeans>${terms}` }));
    expect(verdict(pm(""), "PEPPOL-EN16931-R061")).toBe("error");
    expect(verdict(pm("<ram:SpecifiedTradePaymentTerms><ram:DirectDebitMandateID>M-1</ram:DirectDebitMandateID></ram:SpecifiedTradePaymentTerms>"), "PEPPOL-EN16931-R061")).toBe("success");
  });
  it("R121 and R130 check the gross price's base quantity as well (PEPPOL-EN16931-R121/R130.xml)", () => {
    const line = (gross: string, billed = '<ram:BilledQuantity unitCode="C62">1</ram:BilledQuantity>') =>
      cii(ciiContext() + ciiTx({ lines: `<ram:IncludedSupplyChainTradeLineItem><ram:SpecifiedLineTradeAgreement><ram:GrossPriceProductTradePrice><ram:ChargeAmount>10</ram:ChargeAmount>${gross}</ram:GrossPriceProductTradePrice></ram:SpecifiedLineTradeAgreement><ram:SpecifiedLineTradeDelivery>${billed}</ram:SpecifiedLineTradeDelivery></ram:IncludedSupplyChainTradeLineItem>` }));
    expect(verdict(line('<ram:BasisQuantity unitCode="C62">0</ram:BasisQuantity>'), "PEPPOL-EN16931-R121")).toBe("error");
    expect(verdict(line('<ram:BasisQuantity unitCode="KGM">1</ram:BasisQuantity>'), "PEPPOL-EN16931-R130")).toBe("error");
    expect(verdict(line('<ram:BasisQuantity unitCode="C62">1</ram:BasisQuantity>', "<ram:BilledQuantity>1</ram:BilledQuantity>"), "PEPPOL-EN16931-R130")).toBe("error");
    expect(verdict(line('<ram:BasisQuantity unitCode="C62">1</ram:BasisQuantity>'), "PEPPOL-EN16931-R130")).toBe("success");
  });
  it("R110 and R111 keep line periods inside the invoice period (PEPPOL-EN16931-R110/R111.xml)", () => {
    const d = (v: string) => `<udt:DateTimeString format="102">${v}</udt:DateTimeString>`;
    const xml = cii(ciiContext() + ciiTx({
      lines: `<ram:IncludedSupplyChainTradeLineItem><ram:SpecifiedLineTradeSettlement><ram:BillingSpecifiedPeriod><ram:StartDateTime>${d("20240101")}</ram:StartDateTime><ram:EndDateTime>${d("20240301")}</ram:EndDateTime></ram:BillingSpecifiedPeriod></ram:SpecifiedLineTradeSettlement></ram:IncludedSupplyChainTradeLineItem>`,
      settlement: `<ram:BillingSpecifiedPeriod><ram:StartDateTime>${d("20240201")}</ram:StartDateTime><ram:EndDateTime>${d("20240228")}</ram:EndDateTime></ram:BillingSpecifiedPeriod>`,
    }));
    expect(verdict(xml, "PEPPOL-EN16931-R110")).toBe("error");
    expect(verdict(xml, "PEPPOL-EN16931-R111")).toBe("error");
  });
  it("CL001 checks every attachment's mime code; CL008 the seller and buyer address scheme, present or not", () => {
    expect(verdict(cii('<ram:AttachmentBinaryObject mimeCode="image/tiff"/>'), "PEPPOL-EN16931-CL001")).toBe("error");
    const seller = (uri: string) => cii(ciiContext() + ciiTx({ agreement: `<ram:SellerTradeParty><ram:URIUniversalCommunication>${uri}</ram:URIUniversalCommunication></ram:SellerTradeParty>` }));
    expect(verdict(seller('<ram:URIID schemeID="0207">1</ram:URIID>'), "PEPPOL-EN16931-CL008")).toBe("error");
    expect(verdict(seller("<ram:URIID>a@b.example</ram:URIID>"), "PEPPOL-EN16931-CL008")).toBe("error");
    expect(verdict(seller('<ram:URIID schemeID="0208">0403170701</ram:URIID>'), "PEPPOL-EN16931-CL008")).toBe("success");
  });
  it("P0100 accepts invoice and credit note codes in CII under an approved process (PEPPOL-EN16931-P0100.xml)", () => {
    const doc = (code: string) => cii(`${ciiContext()}<rsm:ExchangedDocument><ram:TypeCode>${code}</ram:TypeCode></rsm:ExchangedDocument>`);
    expect(verdict(doc("381"), "PEPPOL-EN16931-P0100")).toBe("success");
    expect(verdict(doc("380"), "PEPPOL-EN16931-P0100")).toBe("success");
    expect(verdict(doc("999"), "PEPPOL-EN16931-P0100")).toBe("error");
  });
  it("COMMON-R043 checks every URIID, ID and GlobalID with scheme 0208 (PEPPOL-COMMON-R043.xml)", () => {
    const party = (el: string) => cii(ciiContext() + ciiTx({ agreement: `<ram:BuyerTradeParty>${el}</ram:BuyerTradeParty>` }));
    expect(verdict(party('<ram:GlobalID schemeID="0208">0403170702</ram:GlobalID>'), "PEPPOL-COMMON-R043")).toBe("error");
    expect(verdict(party('<ram:ID schemeID="0208">BE0403170701</ram:ID>'), "PEPPOL-COMMON-R043")).toBe("error");
    expect(verdict(party('<ram:URIUniversalCommunication><ram:URIID schemeID="0208">403170701</ram:URIID></ram:URIUniversalCommunication>'), "PEPPOL-COMMON-R043")).toBe("error");
    expect(verdict(party('<ram:GlobalID schemeID="0208">0403170701</ram:GlobalID>'), "PEPPOL-COMMON-R043")).toBe("success");
  });
  it("rules that exist only in Peppol's UBL rules don't run on CII (R008, R044, R046, R051)", () => {
    const xml = cii(ciiContext() + ciiTx({ settlement: '<ram:InvoiceCurrencyCode>EUR</ram:InvoiceCurrencyCode><ram:Empty/><ram:SpecifiedTradeSettlementHeaderMonetarySummation><ram:LineTotalAmount currencyID="NOK">1</ram:LineTotalAmount></ram:SpecifiedTradeSettlementHeaderMonetarySummation>' }));
    for (const id of ["PEPPOL-EN16931-R008", "PEPPOL-EN16931-R044", "PEPPOL-EN16931-R046", "PEPPOL-EN16931-R051"])
      expect(verdict(xml, id), id).toBe("success");
  });
});

describe("Peppol's Dutch national rules on CII (NL-R-001 … NL-R-009)", () => {
  const seller = (address: string, extra = "") =>
    `<ram:SellerTradeParty>${extra}<ram:PostalTradeAddress>${address}<ram:CountryID>NL</ram:CountryID></ram:PostalTradeAddress></ram:SellerTradeParty>`;
  const full = "<ram:PostcodeCode>1234AB</ram:PostcodeCode><ram:LineOne>Straat 1</ram:LineOne><ram:CityName>Groningen</ram:CityName>";
  it("NL-R-002 asks for street, city and post code in a Dutch seller's address", () => {
    expect(verdict(cii(ciiContext() + ciiTx({ agreement: seller("<ram:LineOne>Straat 1</ram:LineOne>") })), "NL-R-002")).toBe("error");
    expect(verdict(cii(ciiContext() + ciiTx({ agreement: seller(full) })), "NL-R-002")).toBe("success");
  });
  it("NL-R-001 needs the invoice reference on a CII credit note (type 381)", () => {
    const doc = (refs: string) =>
      cii(`${ciiContext()}<rsm:ExchangedDocument><ram:TypeCode>381</ram:TypeCode></rsm:ExchangedDocument>${ciiTx({ agreement: seller(full), settlement: refs })}`);
    expect(verdict(doc(""), "NL-R-001")).toBe("error");
    expect(verdict(doc("<ram:InvoiceReferencedDocument><ram:IssuerAssignedID>F-1</ram:IssuerAssignedID></ram:InvoiceReferencedDocument>"), "NL-R-001")).toBe("success");
  });
  it("NL-R-003 asks for a KvK or OIN legal ID; NL-R-007 for payment instructions when money is due", () => {
    const legal = (scheme: string) => `<ram:SpecifiedLegalOrganization><ram:ID schemeID="${scheme}">12345678</ram:ID></ram:SpecifiedLegalOrganization>`;
    expect(verdict(cii(ciiContext() + ciiTx({ agreement: seller(full, legal("0208")) })), "NL-R-003")).toBe("error");
    expect(verdict(cii(ciiContext() + ciiTx({ agreement: seller(full, legal("0106")) })), "NL-R-003")).toBe("success");
    const due = (amount: string) => cii(ciiContext() + ciiTx({ agreement: seller(full), settlement: `<ram:SpecifiedTradeSettlementHeaderMonetarySummation><ram:DuePayableAmount>${amount}</ram:DuePayableAmount></ram:SpecifiedTradeSettlementHeaderMonetarySummation>` }));
    expect(verdict(due("100.00"), "NL-R-007")).toBe("error");
    expect(verdict(due("0.00"), "NL-R-007")).toBe("success");
  });
});

describe("EN 16931 rules the official artefacts check differently from the standard's text", () => {
  const payable = (root: "Invoice" | "CreditNote") =>
    ubl('<cbc:DocumentCurrencyCode>EUR</cbc:DocumentCurrencyCode><cac:LegalMonetaryTotal><cbc:PayableAmount currencyID="EUR">100.00</cbc:PayableAmount></cac:LegalMonetaryTotal>', root);
  it("BR-CO-25 is only a warning on invoices: CEN dropped it from the official rules in 1.3.16", () => {
    expect(verdict(payable("Invoice"), "BR-CO-25", "en16931")).toBe("warning");
    expect(verdict(payable("Invoice"), "BR-CO-25", "peppol")).toBe("warning");
  });
  it("BR-CO-25 never fires on credit notes (CreditNote-unit-UBL/BR-CO-25.xml)", () => {
    expect(verdict(payable("CreditNote"), "BR-CO-25", "en16931")).toBe("success");
  });
  it("BR-CO-25 stays an error for Factur-X, whose rule packs still check it", () => {
    const xml = getSample("factur-x-en16931")!.content
      .replace(/<ram:SpecifiedTradePaymentTerms>[\s\S]*?<\/ram:SpecifiedTradePaymentTerms>/, "");
    expect(xml).not.toContain("SpecifiedTradePaymentTerms");
    expect(verdict(xml, "BR-CO-25", "auto")).toBe("error");
  });
  it("BR-AE-10 accepts any exemption reason code or text (Invoice-unit-UBL/BR-AE-10.xml)", () => {
    const xml = getSample("reverse-charge-valid")!.content.replace(
      "<cbc:TaxExemptionReasonCode>VATEX-EU-AE</cbc:TaxExemptionReasonCode>",
      "<cbc:TaxExemptionReasonCode>10</cbc:TaxExemptionReasonCode>",
    );
    expect(xml).toContain("<cbc:TaxExemptionReasonCode>10</cbc:TaxExemptionReasonCode>");
    expect(verdict(xml, "BR-AE-10", "en16931")).toBe("success");
  });
  it("BR-CO-15 in CII also accepts a grand total equal to the tax basis without a VAT total", () => {
    const totals = (grand: string) =>
      cii(ciiTx({ settlement: `<ram:InvoiceCurrencyCode>EUR</ram:InvoiceCurrencyCode><ram:SpecifiedTradeSettlementHeaderMonetarySummation><ram:TaxBasisTotalAmount>100.00</ram:TaxBasisTotalAmount><ram:GrandTotalAmount>${grand}</ram:GrandTotalAmount></ram:SpecifiedTradeSettlementHeaderMonetarySummation>` }));
    expect(verdict(totals("100.00"), "BR-CO-15", "en16931")).toBe("success");
    expect(verdict(totals("121.00"), "BR-CO-15", "en16931")).toBe("error");
  });
  it("BR-VAT-01 (BR-Z-01, BR-E-01 …): exactly one breakdown row per category; in CII a row also needs a line using it", () => {
    const tax = (cat: string) => `<ram:ApplicableTradeTax><ram:TypeCode>VAT</ram:TypeCode><ram:CategoryCode>${cat}</ram:CategoryCode><ram:RateApplicablePercent>0</ram:RateApplicablePercent></ram:ApplicableTradeTax>`;
    const line = (cat: string) => `<ram:IncludedSupplyChainTradeLineItem><ram:SpecifiedLineTradeSettlement>${tax(cat)}</ram:SpecifiedLineTradeSettlement></ram:IncludedSupplyChainTradeLineItem>`;
    const xml = (lines: string, rows: string) => cii(ciiTx({ lines, settlement: rows }));
    expect(verdict(xml(line("Z"), tax("Z")), "BR-VAT-01", "en16931")).toBe("success");
    expect(verdict(xml(line("Z"), tax("Z") + tax("Z")), "BR-VAT-01", "en16931")).toBe("error");
    expect(verdict(xml("", tax("E")), "BR-VAT-01", "en16931")).toBe("error");
    // In UBL a breakdown row on its own counts as using the category (Invoice-unit-UBL/BR-E-01.xml)
    const row = '<cac:TaxTotal><cac:TaxSubtotal><cac:TaxCategory><cbc:ID>E</cbc:ID><cac:TaxScheme><cbc:ID>VAT</cbc:ID></cac:TaxScheme></cac:TaxCategory></cac:TaxSubtotal></cac:TaxTotal>';
    expect(verdict(ubl(row), "BR-VAT-01", "en16931")).toBe("success");
  });
  it("BR-IC-11 in CII needs a delivery date or a start or end date in the invoice period", () => {
    const k = '<ram:ApplicableTradeTax><ram:TypeCode>VAT</ram:TypeCode><ram:CategoryCode>K</ram:CategoryCode><ram:RateApplicablePercent>0</ram:RateApplicablePercent></ram:ApplicableTradeTax>';
    const xml = (period: string) => cii(ciiTx({ settlement: k + period }));
    expect(verdict(xml("<ram:BillingSpecifiedPeriod><ram:Description>x</ram:Description></ram:BillingSpecifiedPeriod>"), "BR-IC-11", "en16931")).toBe("error");
    expect(verdict(xml('<ram:BillingSpecifiedPeriod><ram:StartDateTime><udt:DateTimeString format="102">20240101</udt:DateTimeString></ram:StartDateTime></ram:BillingSpecifiedPeriod>'), "BR-IC-11", "en16931")).toBe("success");
  });
});
